import React from 'react';

const welcome = () => {
  const styles = `
    * {
      box-sizing: border-box;
      margin: 0;
      padding: 0;
      font-family: 'Arial';
    }

    body {
      background-color: #ffff;
      display: flex;
      height: 100vh;
      justify-content: space-between;
      align-items: center;
      padding: 40px;
    }

    .left-panel {
      display: flex;
      flex-direction: column;
      gap: 15px;
      max-width: 350px;
      margin-left: 100px;
    }

    .left-panel h1 {
      font-size: 28px;
      color: #000;
    }

    .left-panel p {
      font-size: 14px;
      color: #666;
    }

    .button {
      background-color: #007bff;
      color: white;
      border: none;
      padding: 14px 0;
      border-radius: 12px;
      font-size: 16px;
      cursor: pointer;
      width: 100%;
      transition: background 0.3s;
    }

    .button:hover {
      background-color: #0056b3;
    }

    .center-logo {
      display: flex;
      justify-content: center;
      align-items: center;
      flex: 1;
    }

    .center-logo img {
      width: 300px;
      max-width: 100%;
      border-radius: 50%;        
    }

    .signin-button {
      position: absolute;
      top: 20px;
      right: 30px;
      background-color: #007bff;
      color: white;
      border: none;
      padding: 10px 20px;
      border-radius: 8px;
      cursor: pointer;
      font-size: 14px;
    }

    .signin-button:hover {
      background-color: #0056b3;
    }
  `;

  const handleSignupClick = () => {
    window.location.href = 'signup.html';
  };

  return (
    <>
      <style>{styles}</style>
      <button className="signin-button">Sign In</button>

      <div className="left-panel">
        <h1>WELCOME!</h1>
        <p>
          Create an Account<br />
          <small>select what best describe you</small>
        </p>
        <button className="button" onClick={handleSignupClick}>
          Landlord
        </button>
        <button className="button" onClick={handleSignupClick}>
          Tenant
        </button>
      </div>

      <div className="center-logo">
        <img src="renter go.jpg" alt="logo" />
      </div>
    </>
  );
};

export default welcome;
